import os
import openpyxl

out_path = os.environ['OUT_XLSX']
wb = openpyxl.load_workbook(out_path)
ws = wb['Hárok1']

# Build source lookup: brand -> {category: value}
source = {}
for row in range(6, 20):
    brand = ws.cell(row=row, column=2).value  # column B
    if brand is None:
        continue
    source[brand] = {}
    for col in range(3, 10):  # C=3 to I=9
        cat = ws.cell(row=5, column=col).value
        val = ws.cell(row=row, column=col).value
        if cat is not None:
            source[brand][cat] = val

# Target: rows 6-11, columns M(13) to S(19)
for row in range(6, 12):
    brand = ws.cell(row=row, column=12).value  # column L
    if brand is None:
        continue
    for col in range(13, 20):  # M=13 to S=19
        cat = ws.cell(row=5, column=col).value
        if cat is not None and brand in source:
            val = source[brand].get(cat, None)
            ws.cell(row=row, column=col).value = val

wb.save(out_path)
print('Done')
